arguments.command:
python3 -c "
import json
with open('/app/resources/treasury_bulletin_1981_11.json') as f:
    data = json.load(f)

# Search for interest-related keys
def find_keys(d, path=''):
    if isinstance(d, dict):
        for k, v in d.items():
            if 'interest' in k.lower():
                print(f'{path}.{k}')
            find_keys(v, f'{path}.{k}')
    elif isinstance(d, list):
        for i, v in enumerate(d):
            find_keys(v, f'{path}[{i}]')

find_keys(data)
"
